   // linear scan allocators
   private void allocateRegisters(ProcedureInfo procedure) {
      procedure.tempRegisters.clear();
      procedure.spilledTemps.clear();
      procedure.usedSavedRegisters.clear();
      List<LiveInterval> sortedIntervals = new ArrayList<LiveInterval>(procedure.intervals.values());
      Collections.sort(sortedIntervals, new Comparator<LiveInterval>() {
         public int compare(LiveInterval a, LiveInterval b) {
            if (a.start != b.start) {
               return Integer.compare(a.start, b.start);
            }
            return Integer.compare(a.end, b.end);
         }
      });
      List<String> availableRegisters = new ArrayList<String>();
      for (int i = 0; i < 10; i++) {
         availableRegisters.add("t" + i);
      }
      for (int i = 0; i < 8; i++) {
         availableRegisters.add("s" + i);
      }
      List<LiveInterval> active = new ArrayList<LiveInterval>();
      int nextSpillSlot = 0;
      for (LiveInterval current : sortedIntervals) {
         boolean currentCrossesCall = intervalCrossesCall(procedure, current);
         for (int i = active.size() - 1; i >= 0; i--) {
            LiveInterval old = active.get(i);
            if (old.end < current.start) {
               if (!availableRegisters.contains(old.register)) {
                  availableRegisters.add(old.register);
               }
               active.remove(i);
            }
         }
         String freeRegister = null;
         for (int i = 0; i < availableRegisters.size(); i++) {
            String candidate = availableRegisters.get(i);
            if (registerAllowed(candidate, currentCrossesCall)) {
               freeRegister = candidate;
               break;
            }
         }
         if (freeRegister != null) {
            availableRegisters.remove(freeRegister);
            current.register = freeRegister;
            current.spillSlot = -1;
            procedure.tempRegisters.put(current.temp, freeRegister);
            if (freeRegister.startsWith("s")) {
               procedure.usedSavedRegisters.add(freeRegister);
            }
            active.add(current);
         } else {
            LiveInterval farthest = null;
            for (int i = 0; i < active.size(); i++) {
               LiveInterval old = active.get(i);
               if (registerAllowed(old.register, currentCrossesCall)) {
                  if (farthest == null || old.end > farthest.end) {
                     farthest = old;
                  }
               }
            }
            if (farthest != null && farthest.end > current.end) {
               String registerToReuse = farthest.register;
               nextSpillSlot = assignSpillSlot(procedure, farthest, nextSpillSlot);
               active.remove(farthest);
               current.register = registerToReuse;
               current.spillSlot = -1;
               procedure.tempRegisters.put(current.temp, registerToReuse);
               if (registerToReuse.startsWith("s")) {
                  procedure.usedSavedRegisters.add(registerToReuse);
               }
               active.add(current);
            } else {
               nextSpillSlot = assignSpillSlot(procedure, current, nextSpillSlot);
            }
         }
         Collections.sort(active, new Comparator<LiveInterval>() {
            public int compare(LiveInterval a, LiveInterval b) {
               return Integer.compare(a.end, b.end);
            }
         });
      }
   }

   // stack frame layout
   private void layoutStackFrame(ProcedureInfo procedure) {
      procedure.savedRegisterSlots.clear();
      int nextSlot = procedure.incomingArgSlots;
      procedure.spillSlotCount = procedure.spilledTemps.size();
      for (String register : procedure.usedSavedRegisters) {
         procedure.savedRegisterSlots.put(register, nextSlot);
         nextSlot++;
      }
      procedure.stackSlotCount = procedure.incomingArgSlots + procedure.usedSavedRegisters.size()
            + procedure.spillSlotCount;
   }

   // spilling helper
   private int getSpillStackSlot(ProcedureInfo procedure, int temp) {
      Integer spillSlot = procedure.spilledTemps.get(temp);
      if (spillSlot == null) {
         throw new IllegalStateException("TEMP " + temp + " is not assigned a spill slot.");
      }
      return procedure.incomingArgSlots + procedure.usedSavedRegisters.size() + spillSlot;
   }

   // spill aware reader
   private String loadTempIntoRegister(ProcedureInfo procedure, int temp, String scratchRegister) {
      String register = procedure.tempRegisters.get(temp);
      if (register != null) {
         return register;
      }
      int stackSlot = getSpillStackSlot(procedure, temp);
      emitLine("ALOAD " + scratchRegister + " SPILLEDARG " + stackSlot);
      return scratchRegister;
   }

   // output helper
   private void emitLine(String line) {
      generatedCode.append(line);
      generatedCode.append('\n');
   }

   // temp to reg lookup helper
   private String getRegisterForTemp(ProcedureInfo procedure, int temp) {
      String register = procedure.tempRegisters.get(temp);
      if (register == null) {
         throw new IllegalStateException("TEMP " + temp + " has no assigned register; spill handling is required.");
      }
      return register;
   }

   // emitter helper
   private void emitStatement(ProcedureInfo procedure, InstructionInfo instruction) {
      Stmt stmt = instruction.statement;
      if (instruction.label != null) {
         emitLine(instruction.label);
      }
      switch (stmt.f0.which) {
         case 0: {
            // NOOP
            emitLine("NOOP");
            break;
         }
         case 1: {
            // ERROR
            emitLine("ERROR");
            break;
         }
         case 2: {
            // CJUMP TEMP n label
            CJumpStmt cjump = (CJumpStmt) stmt.f0.choice;
            int conditionTemp = tempNumber(cjump.f1);
            String conditionRegister = loadTempIntoRegister(procedure, conditionTemp, "v0");
            emitLine("CJUMP " + conditionRegister + " " + labelName(cjump.f2));
            break;
         }
         case 3: {
            // JUMP label
            JumpStmt jump = (JumpStmt) stmt.f0.choice;
            emitLine("JUMP " + labelName(jump.f1));
            break;
         }

         case 4: {
            HStoreStmt storeStmt = (HStoreStmt) stmt.f0.choice;
            int baseTemp = tempNumber(storeStmt.f1);
            int valueTemp = tempNumber(storeStmt.f3);
            String baseRegister = loadTempIntoRegister(procedure, baseTemp, "v0");
            String valueRegister;
            if (valueTemp == baseTemp
                  && !procedure.tempRegisters.containsKey(valueTemp)) {
               valueRegister = baseRegister;
            } else {
               valueRegister = loadTempIntoRegister(procedure, valueTemp, "v1");
            }
            emitLine("HSTORE " + baseRegister + " " + integerValue(storeStmt.f2) + " " + valueRegister);
            break;
         }

         case 5: {
            HLoadStmt loadStmt = (HLoadStmt) stmt.f0.choice;
            int destinationTemp = tempNumber(loadStmt.f1);
            int baseTemp = tempNumber(loadStmt.f2);
            String baseRegister = loadTempIntoRegister(procedure, baseTemp, "v0");
            String destinationRegister = procedure.tempRegisters.get(destinationTemp);
            boolean destinationSpilled = (destinationRegister == null);
            if (destinationSpilled) {
               destinationRegister = "v1";
            }
            emitLine("HLOAD " + destinationRegister + " " + baseRegister + " " + integerValue(loadStmt.f3));
            if (destinationSpilled) {
               int slot = getSpillStackSlot(procedure, destinationTemp);
               emitLine("ASTORE SPILLEDARG " + slot + " v1");
            }
            break;
         }
         case 6: {
            // MOVE statement
            MoveStmt move = (MoveStmt) stmt.f0.choice;
            emitMoveStatement(procedure, move);
            break;
         }
         case 7: {
            PrintStmt printStmt = (PrintStmt) stmt.f0.choice;
            SimpleExp value = printStmt.f1;
            String valueText;
            if (value.f0.which == 0) {
               Temp temp = (Temp) value.f0.choice;
               int tempId = tempNumber(temp);
               valueText = loadTempIntoRegister(procedure, tempId, "v0");
            } else {
               valueText = getSimpleExpText(procedure, value);
            }
            emitLine("PRINT " + valueText);
            break;
         }
         default: {
            throw new IllegalStateException("Statement type not implemented yet: " + stmt.f0.which);
         }
      }
   }

   // helper for simple expression
   private String getSimpleExpText(ProcedureInfo procedure, SimpleExp exp) {
      switch (exp.f0.which) {
         case 0: {
            // TEMP n
            Temp temp = (Temp) exp.f0.choice;
            return getRegisterForTemp(procedure, tempNumber(temp));
         }
         case 1: {
            // Integer literal
            IntegerLiteral literal = (IntegerLiteral) exp.f0.choice;
            return Integer.toString(integerValue(literal));
         }
         case 2: {
            // Label
            Label label = (Label) exp.f0.choice;
            return labelName(label);
         }
         default:
            throw new IllegalStateException("Unknown SimpleExp type");
      }
   }

   // emitting all statements
   private void emitStatements(ProcedureInfo procedure) {
      for (InstructionInfo instruction : procedure.instructions) {
         emitStatement(procedure, instruction);
      }
   }

   // prologue and epilogue generator
   private void emitProcedurePrologue(ProcedureInfo procedure) {
      for (String register : procedure.usedSavedRegisters) {
         Integer slot = procedure.savedRegisterSlots.get(register);
         if (slot == null) {
            throw new IllegalStateException("Missing stack slot for saved register " + register);
         }
         emitLine("ASTORE SPILLEDARG " + slot + " " + register);
      }
   }

   private void emitProcedureEpilogue(ProcedureInfo procedure) {
      for (String register : procedure.usedSavedRegisters) {
         Integer slot = procedure.savedRegisterSlots.get(register);
         if (slot == null) {
            throw new IllegalStateException("Missing stack slot for saved register " + register);
         }
         emitLine("ALOAD " + register + " SPILLEDARG " + slot);
      }
   }

   // footer helper
   private void emitProcedureFooter(ProcedureInfo procedure) {
      if (procedure.spilledTemps.isEmpty()) {
         emitLine("// NOTSPILLED");
      } else {
         emitLine("// SPILLED");
      }
   }

   // helper for move statement
   private void emitMoveStatement(ProcedureInfo procedure, MoveStmt move) {
      if (move.f2.f0.which == 0) {
         emitCallMove(procedure, move);
         return;
      }
      if (move.f2.f0.which == 1) {
         emitHAllocateMove(procedure, move);
         return;
      }
      if (move.f2.f0.which == 2) {
         BinOp binOp = (BinOp) move.f2.f0.choice;
         emitBinaryMove(procedure, move);
         return;
      }
      if (move.f2.f0.which != 3) {
         throw new IllegalStateException("MOVE expression not implemented yet: " + move.f2.f0.which);
      }

      int destinationTemp = tempNumber(move.f1);
      SimpleExp source = (SimpleExp) move.f2.f0.choice;
      String sourceRegisterOrValue;
      if (source.f0.which == 0) {
         Temp sourceTemp = (Temp) source.f0.choice;
         int sourceTempId = tempNumber(sourceTemp);
         sourceRegisterOrValue = loadTempIntoRegister(procedure, sourceTempId, "v0");
      } else {
         sourceRegisterOrValue = getSimpleExpText(procedure, source);
      }
      String destinationRegister = procedure.tempRegisters.get(destinationTemp);
      if (destinationRegister != null) {
         emitLine("MOVE " + destinationRegister + " " + sourceRegisterOrValue);
      } else {
         int destinationSlot = getSpillStackSlot(procedure, destinationTemp);
         if (source.f0.which == 0 && sourceRegisterOrValue.equals("v0")) {
            emitLine("ASTORE SPILLEDARG " + destinationSlot + " v0");
         } else {
            emitLine("MOVE v1 " + sourceRegisterOrValue);
            emitLine("ASTORE SPILLEDARG " + destinationSlot + " v1");
         }
      }
   }

   // binary operation helper

   private void emitBinaryMove(ProcedureInfo procedure, MoveStmt move) {
      int destinationTemp = tempNumber(move.f1);
      BinOp binOp = (BinOp) move.f2.f0.choice;
      int firstTemp = tempNumber(binOp.f1);
      String firstRegister = loadTempIntoRegister(procedure, firstTemp, "v0");
      String secondOperand;
      boolean secondIsSpilledTemp = false;
      int secondTemp = -1;
      if (binOp.f2.f0.which == 0) {
         Temp temp = (Temp) binOp.f2.f0.choice;
         secondTemp = tempNumber(temp);
         if (procedure.tempRegisters.get(secondTemp) == null) {
            secondIsSpilledTemp = true;
            secondOperand = loadTempIntoRegister(procedure, secondTemp, "v1");
         } else {
            secondOperand = procedure.tempRegisters.get(secondTemp);
         }
      } else {
         secondOperand = getSimpleExpText(procedure, binOp.f2);
      }
      String destinationRegister = procedure.tempRegisters.get(destinationTemp);
      boolean destinationSpilled = (destinationRegister == null);
      if (destinationSpilled) {
         destinationRegister = "v0";
      }
      String operator = ((NodeToken) binOp.f0.f0.choice).tokenImage;
      if (!operator.equals("LE") && !operator.equals("NE") && !operator.equals("PLUS") && !operator.equals("MINUS")
            && !operator.equals("TIMES") && !operator.equals("DIV")) {
         throw new IllegalStateException("Unsupported binary operator: " + operator);
      }
      emitLine("MOVE " + destinationRegister + " " + operator + " " + firstRegister + " " + secondOperand);
      if (destinationSpilled) {
         int destinationSlot = getSpillStackSlot(procedure, destinationTemp);
         emitLine("ASTORE SPILLEDARG " + destinationSlot + " " + destinationRegister);
      }
   }

   // hallocate emitter

   private void emitHAllocateMove(ProcedureInfo procedure, MoveStmt move) {
      int destinationTemp = tempNumber(move.f1);
      HAllocate halloc = (HAllocate) move.f2.f0.choice;
      String sizeOperand;
      if (halloc.f1.f0.which == 0) {
         Temp sizeTemp = (Temp) halloc.f1.f0.choice;
         int sizeTempId = tempNumber(sizeTemp);
         sizeOperand = loadTempIntoRegister(procedure, sizeTempId, "v0");
      } else {
         sizeOperand = getSimpleExpText(procedure, halloc.f1);
      }
      String destinationRegister = procedure.tempRegisters.get(destinationTemp);
      boolean destinationSpilled = (destinationRegister == null);
      if (destinationSpilled) {
         destinationRegister = "v0";
      }
      emitLine("MOVE " + destinationRegister + " HALLOCATE " + sizeOperand);
      if (destinationSpilled) {
         int destinationSlot = getSpillStackSlot(procedure, destinationTemp);
         emitLine("ASTORE SPILLEDARG " + destinationSlot + " " + destinationRegister);
      }
   }

   // call helper
   private void emitCallMove(ProcedureInfo procedure, MoveStmt move) {
      int destinationTemp = tempNumber(move.f1);
      Call call = (Call) move.f2.f0.choice;
      int argumentCount = call.f3.size();
      for (int i = 0; i < argumentCount && i < 4; i++) {
         Temp argument = (Temp) call.f3.elementAt(i);
         int argumentTemp = tempNumber(argument);
         String argumentRegister = loadTempIntoRegister(procedure, argumentTemp, "v0");
         emitLine("MOVE a" + i + " " + argumentRegister);
      }
      for (int i = 4; i < argumentCount; i++) {
         Temp argument = (Temp) call.f3.elementAt(i);
         int argumentTemp = tempNumber(argument);
         String argumentRegister = loadTempIntoRegister(procedure, argumentTemp, "v0");
         emitLine("PASSARG " + (i - 3) + " " + argumentRegister);
      }
      String target;
      if (call.f1.f0.which == 0) {
         Temp targetTempNode = (Temp) call.f1.f0.choice;
         int targetTemp = tempNumber(targetTempNode);
         target = loadTempIntoRegister(procedure, targetTemp, "v1");
      } else {
         target = getSimpleExpText(procedure, call.f1);
      }
      emitLine("CALL " + target);
      String destinationRegister = procedure.tempRegisters.get(destinationTemp);
      if (destinationRegister != null) {
         emitLine("MOVE " + destinationRegister + " v0");
      } else {
         int destinationSlot = getSpillStackSlot(procedure, destinationTemp);
         emitLine("ASTORE SPILLEDARG " + destinationSlot + " v0");
      }
   }

   private void emitProcedureArguments(ProcedureInfo procedure) {
      int registerArgCount = Math.min(procedure.argumentCount, 4);
      for (int i = 0; i < registerArgCount; i++) {
         String destination = procedure.tempRegisters.get(i);
         if (destination != null) {
            emitLine("MOVE " + destination + " a" + i);
         } else {
            int slot = getSpillStackSlot(procedure, i);
            emitLine("ASTORE SPILLEDARG " + slot + " a" + i);
         }
      }
      for (int i = 4; i < procedure.argumentCount; i++) {
         emitLine("ALOAD v1 SPILLEDARG " + (i - 4));
         String destination = procedure.tempRegisters.get(i);
         if (destination != null) {
            emitLine("MOVE " + destination + " v1");
         } else {
            int slot = getSpillStackSlot(procedure, i);
            emitLine("ASTORE SPILLEDARG " + slot + " v1");
         }
      }
   }

   // program output helper
   private void emitProgram() {
      generatedCode.setLength(0);
      ProcedureInfo mainProcedure = procedures.get(0);
      emitLine("MAIN [0] [" + mainProcedure.stackSlotCount + "] [" + mainProcedure.maxCallArgs + "]");
      emitStatements(mainProcedure);
      emitLine("END");
      emitProcedureFooter(mainProcedure);
      for (int i = 1; i < procedures.size(); i++) {
         ProcedureInfo procedure = procedures.get(i);
         emitLine(procedure.name + " [" + procedure.argumentCount + "] [" + procedure.stackSlotCount + "] ["
               + procedure.maxCallArgs + "]");
         emitProcedurePrologue(procedure);
         emitProcedureArguments(procedure);
         emitStatements(procedure);
         SimpleExp returnValue = procedure.returnValue;
         if (returnValue.f0.which == 0) {
            Temp returnTemp = (Temp) returnValue.f0.choice;
            String source = loadTempIntoRegister(procedure, tempNumber(returnTemp), "v0");
            emitLine("MOVE v0 " + source);
         } else {
            emitLine("MOVE v0 " + getSimpleExpText(procedure, returnValue));
         }
         emitProcedureEpilogue(procedure);
         emitLine("END");
         emitProcedureFooter(procedure);
      }
   }

   public R visit(NodeList n, A argu) {
      R _ret = null;
      int _count = 0;
      for (Enumeration<Node> e = n.elements(); e.hasMoreElements();) {
         e.nextElement().accept(this, argu);
         _count++;
      }
      return _ret;
   }

   public R visit(NodeListOptional n, A argu) {
      if (n.present()) {
         R _ret = null;
         int _count = 0;
         for (Enumeration<Node> e = n.elements(); e.hasMoreElements();) {
            e.nextElement().accept(this, argu);
            _count++;
         }
         return _ret;
      } else
         return null;
   }

