   /**
    * f0 -> Label()
    * f1 -> "["
    * f2 -> IntegerLiteral()
    * f3 -> "]"
    * f4 -> StmtExp()
    */
   public R visit(Procedure n, A argu) {
      String name = labelName(n.f0);
      int argumentCount = integerValue(n.f2);
      currentProcedure = new ProcedureInfo(name, argumentCount);
      currentProcedure.returnValue = n.f4.f3;
      procedures.add(currentProcedure);
      collectStmtList(n.f4.f1);
      currentProcedure = null;
      return null;
   }

   //
   // User-generated visitor methods below
   //

   /**
    * f0 -> "MAIN"
    * f1 -> StmtList()
    * f2 -> "END"
    * f3 -> ( Procedure() )*
    * f4 -> <EOF>
    */
   public R visit(Goal n, A argu) {
      procedures.clear();
      // Collect MAIN first.
      currentProcedure = new ProcedureInfo("MAIN", 0);
      procedures.add(currentProcedure);
      collectStmtList(n.f1);
      // Collect each procedure independently.
      for (int i = 0; i < n.f3.size(); i++) {
         Procedure procedure = (Procedure) n.f3.elementAt(i);
         procedure.accept(this, argu);
      }
      for (ProcedureInfo procedure : procedures) {
         buildControlFlow(procedure);
      }
      // Calculate liveIn and liveOut for every procedure.
      for (ProcedureInfo procedure : procedures) {
         analyzeLiveness(procedure);
      }
      // Build live intervals for every procedure.
      for (ProcedureInfo procedure : procedures) {
         buildLiveIntervals(procedure);
      }
      // Allocate registers and spill slots for each procedure.
      for (ProcedureInfo procedure : procedures) {
         allocateRegisters(procedure);
      }
      // stack frame layout
      for (ProcedureInfo procedure : procedures) {
         layoutStackFrame(procedure);
      }
      emitProgram();
      System.out.print(generatedCode.toString());
      currentProcedure = null;
      return null;

   }

